		/* common.mdsr.updateMasterMdSrSrDetailPop */
			UPDATE KEPASRDT SET



               RUB_TYPE=#{st_rub_type},    
               RUB_REMARK=#{st_rub_remark},    
               FF_DATE=SYSDATE,



			   RECV_FLAG=#{st_recv_flag}
			WHERE USER_ID=#{st_sr_user_id}    
               AND SR_NO=#{st_sr_no}

