/* common.mdsr.selectMasterMdSrExcelRe */ SELECT XXX.BUYER_NAME AS 고객사명 , XXX.SOURCING_STATUS AS 진행상태 , XXX.BUYER_ITEM_NO AS 품목코드 , XXX.QUOTATION_NO AS 견적번호 , XXX.QUOTATION_SEQ AS 견적순번 , XXX.REVICNT AS "차수(B/S)" , XXX.BTOA_DATE AS 견적의뢰일 , XXX.BTOA_END_DATE AS 회신요청일 , XXX.ATOB_DATE AS 견적제출일 , XXX.DESCRIPTION AS 품목명 , XXX.SPECIFICATION AS 규격 , XXX.MAKER_NAME AS 제조사 , XXX.ORIGIN_NAME AS 원산지 , XXX.UNIT_MEASURE AS 단위 , XXX.ATOS_DATE AS 견적요청일 , XXX.ATOS_END_DATE AS 견적마감일 , XXX.ITEM_QTY AS 수량 , XXX.BUYER_TARGET_PRICE AS "목표단가(고)" , XXX.ADMIN_TARGET_PRICE AS "목표단가(운)" , XXX.ATOB_UNIT_PRICE AS 매출단가 , XXX.STOA_LIST_PRICE AS 매입단가 , XXX.AGENT_NAME AS 선정협력사 , XXX.BTOA_USER_NAME AS 요청자 , XXX.BTOA_USER_DEPT AS 요청부서 , XXX.KEP_USER_NAME AS 담당자 , XXX.BTOA_REMARK AS 고객사비고 , XXX.CONFIRM_DATE AS 합의일자 , XXX.PROCESS_TYPE AS 거래유형 , XXX.WAREHOUSE_CODE AS 물류센터 , XXX.IMPORT_FLAG AS 수입여부 , XXX.PLANT , XXX.BUYER AS 고객사코드 , XXX.KEP_SPECIFICATION AS 고객사규격 , XXX.REF_NO AS 관리번호 FROM ( SELECT YYY.* , COUNT(*) OVER() AS TOTNUM , ROWNUM RN FROM (
SELECT /*selectMasterMdSrExcelRe*/ Z.BUYER, DECODE(TRIM(Z.PLANT),'',Z.BUYER_NAME,Z.BUYER_NAME||'('||Z.PLANT||')') AS BUYER_NAME, Z.QUOTATION_NO, Z.QUOTATION_SEQ, Z.REVISION, Z.REVISION || '/' || Z.AGENT_REVISION AS REVICNT, Z.SOURCING_STATUS, Z.BTOA_DATE, Z.DESCRIPTION, Z.ATOS_DATE, Z.ATOB_UNIT_PRICE, Z.BTOA_USER_NAME, Z.KEP_USER_ID, TO_CHAR(TO_DATE(Z.BTOA_END_DATE,'YYYY/MM/DD'),'YYYY/MM/DD') || ' ' || SUBSTR(Z.BTOA_END_TIME,0,2)||':'||SUBSTR(Z.BTOA_END_TIME,3,2) AS BTOA_END_DATE, Z.SPECIFICATION, DECODE(Z.ATOS_END_DATE,'','',TO_CHAR(TO_DATE(Z.ATOS_END_DATE,'YYYY/MM/DD'),'YYYY/MM/DD') || ' ' || SUBSTR(Z.ATOS_END_TIME,0,2)||':'||SUBSTR(Z.ATOS_END_TIME,3,2)) AS ATOS_END_DATE, Z.STOA_LIST_PRICE, Z.BTOA_USER_DEPT, Z.BTOA_REMARK, Z.ATOB_REMARK, Z.SCM_REMARK, DECODE(Z.BTOA_REMARK,'',0,1) AS BTOA_REMARK_IMG, DECODE(Z.SCM_REMARK,'',0,1) AS SCM_REMARK_IMG, Z.BUYER_ITEM_NO, Z.DELAY_STATUS, Z.MAKER_NAME, Z.ORIGIN_NAME, Z.UNIT_MEASURE, Z.ITEM_QTY, Z.AGENT_NAME, Z.IMAGE_KEY, DECODE(Z.IMAGE_KEY,'',2,3) AS IMAGE_KEY_IMG, Z.KEP_USER_NAME, Z.REG_ITEM_NO, Z.AGENT, Z.BTOA_USER_ID, Z.AGENT_REVISION, DECODE(Z.ATOB_DATE,'','',TO_CHAR(TO_DATE(Z.ATOB_DATE,'YYYY/MM/DD'),'YYYY/MM/DD') || ' ' || SUBSTR(Z.ATOB_TIME,0,2)||':'||SUBSTR(Z.ATOB_TIME,3,2)) AS ATOB_DATE, Z.ATOS_END_FLAG, Z.CMS_USER_NAME, Z.REF_NO, Z.CANCEL_REMARK, DECODE(Z.CANCEL_REMARK,'',0,1) AS CANCEL_REMARK_IMG, Z.CMS_CATLG_ID, Z.CMS_CATEG_ID, Z.REFER_MAPPING_FLAG, Z.BUYER_TARGET_PRICE, Z.ADMIN_TARGET_PRICE, Z.QUOTA_CNT , Z.CONFIRM_DATE , Z.PROCESS_TYPE , Z.IMPORT_FLAG , Z.WAREHOUSE_CODE , (SELECT MAX(TARGET) FROM KEPMGPDT GT, ICOMTRGW GW WHERE GT.BUYER = Z.BUYER AND GT.QUOTATION_NO = Z.QUOTATION_NO AND GT.QUOTATION_SEQ = Z.QUOTATION_SEQ AND GT.REVISION = Z.REVISION AND GT.STATUS <> 'D' AND GW.COM_CODE = 'KRKORE0001' AND GW.KEY_2 = GT.BUYER AND GW.KEY_1 = GT.PM_NO ) DOCU_NO , DECODE(Z.DELAY_STATUS,'지연','4','정상','5','진행중','6') AS DELAY_STATUS_IMG , Z.PLANT , Z.KEP_SPECIFICATION FROM ( SELECT Y.BUYER, Y.BUYER_NAME, Y.QUOTATION_NO, Y.QUOTATION_SEQ, Y.REVISION, Y.BTOA_DATE, Y.DESCRIPTION, Y.ATOS_DATE, Y.ATOB_UNIT_PRICE, Y.BTOA_USER_NAME, Y.KEP_USER_ID, Y.SOURCING_STATUS, Y.BTOA_END_DATE, Y.SPECIFICATION, Y.ATOS_END_DATE, Y.STOA_LIST_PRICE, Y.BTOA_USER_DEPT, Y.BTOA_REMARK, Y.ATOB_REMARK, Y.SCM_REMARK, Y.BUYER_ITEM_NO, Y.DELAY_STATUS, Y.MAKER_NAME, Y.ORIGIN_NAME, Y.UNIT_MEASURE, Y.ITEM_QTY, Y.AGENT_NAME, Y.IMAGE_KEY, Y.KEP_USER_NAME, Y.REG_ITEM_NO, Y.AGENT, Y.BTOA_USER_ID, Y.BTOA_END_TIME, Y.ATOS_END_TIME, Y.AGENT_REVISION, Y.ATOB_DATE, Y.ATOB_TIME, Y.ATOS_END_FLAG, Y.CMS_USER_NAME, Y.REF_NO, Y.CANCEL_REMARK , Y.CMS_CATLG_ID, Y.CMS_CATEG_ID, Y.REFER_MAPPING_FLAG, Y.PLANT, Y.BUYER_TARGET_PRICE, Y.ADMIN_TARGET_PRICE, Y.QUOTA_CNT , Y.CONFIRM_DATE , Y.PROCESS_TYPE , Y.IMPORT_FLAG , Y.WAREHOUSE_CODE , Y.KEP_SPECIFICATION FROM ( SELECT X.BUYER, X.BUYER_NAME, X.QUOTATION_NO, X.QUOTATION_SEQ, X.REVISION, X.BTOA_DATE, X.DESCRIPTION, X.ATOS_DATE, X.ATOB_UNIT_PRICE, X.BTOA_USER_NAME, X.KEP_USER_ID, X.SOURCING_STATUS, X.BTOA_END_DATE, X.SPECIFICATION, X.ATOS_END_DATE, X.STOA_LIST_PRICE, X.BTOA_USER_DEPT, X.BTOA_REMARK, X.ATOB_REMARK, X.SCM_REMARK, X.BUYER_ITEM_NO, X.DELAY_STATUS, X.MAKER_NAME, X.ORIGIN_NAME, X.UNIT_MEASURE, X.ITEM_QTY, X.AGENT_NAME, X.IMAGE_KEY, X.KEP_USER_NAME, X.REG_ITEM_NO, X.AGENT, X.BTOA_USER_ID, X.BTOA_END_TIME, X.ATOS_END_TIME, X.AGENT_REVISION, X.ATOB_DATE, X.ATOB_TIME, X.ATOS_END_FLAG, X.CMS_USER_NAME, X.REF_NO, X.CANCEL_REMARK , X.CMS_CATLG_ID, X.CMS_CATEG_ID, X.REFER_MAPPING_FLAG, X.PLANT, X.BUYER_TARGET_PRICE, X.ADMIN_TARGET_PRICE, X.QUOTA_CNT , X.CONFIRM_DATE , X.PROCESS_TYPE , X.IMPORT_FLAG , X.WAREHOUSE_CODE , X.KEP_SPECIFICATION FROM ( SELECT
A.BUYER, CP.COM_NAME_LOC AS BUYER_NAME, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION, A.BTOA_DATE, A.DESCRIPTION, B.ATOS_DATE, A.ATOB_UNIT_PRICE, A.BTOA_USER_NAME, A.KEP_USER_ID, CASE WHEN A.RECV_FLAG = 'GD' THEN '견적취소' WHEN A.RECV_FLAG = 'GS' THEN '결재진행중' WHEN A.RECV_FLAG = 'GR' THEN '결재반려' WHEN A.RECV_FLAG = 'PM' THEN CASE WHEN A.ATOB_SEND_FLAG = 'N' AND (SELECT COUNT(*) FROM ICOMBYIT_ADD WHERE COM_CODE = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND STATUS = 'E' ) > 0 THEN '카탈로그등록중 오류발생' WHEN A.ATOB_SEND_FLAG = 'N' THEN '내부품의및카탈로그등록중' WHEN A.ATOB_SEND_FLAG = 'Y' THEN 'BPA등록중' END WHEN A.RECV_FLAG = 'CC' THEN '장바구니' WHEN A.RECV_FLAG = 'CM' THEN CASE WHEN (SELECT COUNT(*) FROM ICOMCMPY CMPY, ICOMBYIT BYIT WHERE CMPY.COM_CODE = A.BUYER AND CMPY.BYCA_COMORG_CODE = BYIT.BUYER AND BYIT.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND BYIT.PRODUCT_CLOSE_FLAG = 'G') = 1 THEN '합의완료(가합의)' ELSE '합의완료' END WHEN A.RECV_FLAG = 'PC' THEN '발주' WHEN A.RECV_FLAG = 'NW' THEN '고객사견적의뢰' WHEN A.RECV_FLAG = 'CR' THEN '고객사견적의뢰' WHEN A.RECV_FLAG = 'RJ' THEN '고객사견적의뢰' WHEN A.KEP_USER_ID IS NULL THEN '고객사견적의뢰' ELSE CASE WHEN B.AGENT_REVISION = 1 AND A.ATOB_UNIT_PRICE = 0 AND A.ATOB_SEND_FLAG = 'N' AND B.BID_SUCCESS_FLAG <> 'Y' THEN '협력사견적요청' WHEN B.AGENT_REVISION <> 1 AND A.ATOB_UNIT_PRICE = 0 AND A.ATOB_SEND_FLAG = 'N' AND B.BID_SUCCESS_FLAG <> 'Y' THEN '협력사재견적요청' WHEN A.ATOB_UNIT_PRICE = 0 AND A.ATOB_SEND_FLAG = 'N' AND B.BID_SUCCESS_FLAG = 'Y' THEN '협력사선정완료' WHEN A.BTOA_NEGO_PRICE = 0 AND A.ATOB_UNIT_PRICE <> 0 AND A.ATOB_SEND_FLAG = 'Y' THEN '고객사견적제시' WHEN A.BTOA_NEGO_PRICE <> 0 AND A.ATOB_UNIT_PRICE = 0 AND A.ATOB_SEND_FLAG = 'Y' THEN '고객사NEGO의뢰' WHEN A.BTOA_NEGO_PRICE <> 0 AND A.ATOB_UNIT_PRICE <> 0 AND A.ATOB_SEND_FLAG = 'Y' THEN '고객사NEGO견적제출' END END AS SOURCING_STATUS, A.BTOA_END_DATE, A.SPECIFICATION, B.ATOS_END_DATE, CASE WHEN B.BID_SUCCESS_FLAG = 'Y' THEN B.STOA_LIST_PRICE ELSE NULL END AS STOA_LIST_PRICE, DP.TEXT1 AS BTOA_USER_DEPT, A.BTOA_REMARK, A.ATOB_REMARK, A.SCM_REMARK, A.BUYER_ITEM_NO, CASE WHEN A.ATOB_SEND_FLAG = 'N' THEN CASE WHEN SIGN(TO_CHAR(SYSDATE,'YYYYMMDD') - A.BTOA_END_DATE) = 1 THEN '지연' ELSE '진행중' END ELSE CASE WHEN SIGN(A.ATOB_DATE - A.BTOA_END_DATE) = 1 THEN '지연' ELSE '정상' END END AS DELAY_STATUS, A.MAKER_NAME, OG.TEXT2 AS ORIGIN_NAME, A.UNIT_MEASURE, A.ITEM_QTY, AC.COM_NAME_LOC AS AGENT_NAME, A.IMAGE_KEY, LR.USER_NAME_LOC AS KEP_USER_NAME, A.REG_ITEM_NO, AC.COM_CODE AS AGENT, A.BTOA_USER_ID, A.BTOA_END_TIME, B.ATOS_END_TIME, B.AGENT_REVISION, A.ATOB_DATE, A.ATOB_TIME, CASE WHEN B.ATOS_END_DATE||B.ATOS_END_TIME < TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS') THEN 'Y' ELSE 'N' END AS ATOS_END_FLAG, CR.USER_NAME_LOC AS CMS_USER_NAME, A.REF_NO, A.CANCEL_REMARK, CASE WHEN MK.VALUE1 = 1 THEN CASE WHEN A.CMS_CATLG_ID IN ('TALK','PASS') THEN A.CMS_CATLG_ID ELSE CMS.CMS_CATLG_ID END ELSE 'NON' END AS CMS_CATLG_ID, CMS.CMS_CATEG_ID, A.REFER_MAPPING_FLAG, A.PLANT, A.BUYER_TARGET_PRICE, A.ADMIN_TARGET_PRICE, (SELECT COUNT(*) FROM KEPQTDT WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND STATUS = 'C') AS QUOTA_CNT , DECODE(A.CONFIRM_DATE,'','',TO_CHAR(TO_DATE(A.CONFIRM_DATE,'YYYY/MM/DD'),'YYYY/MM/DD')) AS CONFIRM_DATE , DECODE(A.PROCESS_TYPE, '0','직납','1','재고','2','TR','3','VMI',' ') AS PROCESS_TYPE , DECODE(A.IMPORT_FLAG, 'N','미수입','Y','수입') AS IMPORT_FLAG , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.WAREHOUSE_CODE) AS WAREHOUSE_CODE , A.KEP_SPECIFICATION FROM KEPRQDT A LEFT OUTER JOIN ( SELECT Y.BUYER , Y.QUOTATION_NO , Y.QUOTATION_SEQ , Y.REVISION ,REGEXP_SUBSTR(QTDT_KEY,'[^^]+',1,1) BID_SUCCESS_FLAG ,REGEXP_SUBSTR(QTDT_KEY,'[^^]+',1,2) AGENT ,REGEXP_SUBSTR(QTDT_KEY,'[^^]+',1,3) ATOS_END_TIME ,REGEXP_SUBSTR(QTDT_KEY,'[^^]+',1,4) ATOS_END_DATE ,REGEXP_SUBSTR(QTDT_KEY,'[^^]+',1,5) AGENT_REVISION ,REGEXP_SUBSTR(QTDT_KEY,'[^^]+',1,6) STOA_LIST_PRICE ,REGEXP_SUBSTR(QTDT_KEY,'[^^]+',1,7) ATOS_DATE FROM( SELECT X.BUYER , QUOTATION_NO , QUOTATION_SEQ , REVISION ,MAX(BID_SUCCESS_FLAG||'^'||AGENT||'^'||ATOS_END_TIME||'^'||ATOS_END_DATE ||'^'||AGENT_REVISION||'^'||STOA_LIST_PRICE||'^'||ATOS_DATE) QTDT_KEY FROM KEPQTDT X WHERE X.BUYER = #{st_req_data_buyer} AND X.STATUS = 'C' GROUP BY X.BUYER , QUOTATION_NO , QUOTATION_SEQ , REVISION ) Y ) B ON (1 = 1 AND B.BUYER = A.BUYER AND B.QUOTATION_NO = A.QUOTATION_NO AND B.QUOTATION_SEQ = A.QUOTATION_SEQ AND B.REVISION = A.REVISION ) LEFT OUTER JOIN ICOMCMPY AC ON (1 = 1 AND AC.COM_CODE = B.AGENT AND AC.STATUS IN ('C','R') AND B.BID_SUCCESS_FLAG = 'Y' ) LEFT OUTER JOIN CMSCATLG CMS ON (1 = 1 AND CMS.CMS_CATLG_ID = A.CMS_CATLG_ID AND CMS.STD_FLAG = 'Y' ) LEFT OUTER JOIN ICOMCOD1 MK ON (1 = 1 AND MK.CODE = A.MAKER_CODE AND MK.TYPE = 'M104' AND MK.FLAG = 'Y' ) LEFT OUTER JOIN ICOMCMPY CP ON (1 = 1 AND CP.COM_CODE = A.BUYER AND CP.STATUS IN ('C','R') ) LEFT OUTER JOIN ICOMCOD2 DP ON (1 = 1 AND DP.COMPANY_CODE = A.BUYER AND DP.TYPE = 'C001' AND DP.CODE = A.BTOA_USER_DEPT AND DP.FLAG = 'Y' ) LEFT OUTER JOIN ICOMCOD1 OG ON (1 = 1 AND OG.TYPE = 'M001' AND OG.CODE = A.ORIGIN_CODE AND OG.FLAG = 'Y' ) LEFT OUTER JOIN ICOMLUSR LR ON (1 = 1 AND LR.USER_ID = A.KEP_USER_ID AND LR.STATUS IN ('C','R') ) LEFT OUTER JOIN ICOMLUSR CR ON (1 = 1 AND CR.USER_ID = A.CMS_USER_ID AND CR.STATUS IN ('C','R') ) WHERE A.BTOA_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND A.BUYER = #{st_req_data_buyer} AND A.SO_CA_FLAG = 'SO' AND A.STATUS IN ('C','R') AND A.RECV_FLAG NOT IN ('NG','NR','TS') ) X ) Y ) Z
) YYY ) XXX
ORDER BY 1,2,3,4,5
